new = """    if (!TERM_RE.test(term)) return { kind: 'invalid', reason: `"${term}" is not a policy term (a kebab-case rule name or under:<dir>, optionally reject:-prefixed)` };
    const bare = term.startsWith('reject:') ? term.slice('reject:'.length) : term;
    if (bare.startsWith(UNDER_PREFIX) && !underRule(bare)) {
